// Unseal accessors — every call site imports these, never the
// raw arrays. Add a new fragment by appending an array AND an
// accessor; never inline a raw literal in a module.
// ─────────────────────────────────────────────────────────────

String unsealEndpoint() => unseal(_endpoint);
String unsealGcdBase() => unseal(_gcdBase);
String unsealAttributionKey() => unseal(_attributionKey);
String unsealMessagingProject() => unseal(_messagingProject);

String unsealUaProduct() => unseal(_uaProduct);
String unsealUaLinuxOpen() => unseal(_uaLinuxOpen);
String unsealUaBuildLabel() => unseal(_uaBuildLabel);
String unsealUaBuildClose() => unseal(_uaBuildClose);
String unsealUaEngineLabel() => unseal(_uaEngineLabel);
String unsealUaEngineTail() => unseal(_uaEngineTail);
String unsealUaChromeLabel() => unseal(_uaChromeLabel);
