String unsealChromeVersion() => unseal(_chromeVersion);
String unsealWebkitVersion() => unseal(_webkitVersion);

String unsealUaAppIdToken() => unseal(_uaAppIdToken);
String unsealUaAppNameToken() => unseal(_uaAppNameToken);
String unsealAppNameToken() => unseal(_appNameToken);

String unsealJsSafeArea() => unseal(_jsSafeArea);
String unsealJsKeyboard() => unseal(_jsKeyboard);
