/// Builds the GCD rescue URL for a given install. Returns `""`
/// when the base is not packed yet — callers treat that as
/// "GCD rescue unavailable" and keep whatever the SDK delivered.
String unsealGcdCallUrl(String bundleId, String deviceId) {
  final String base = unsealGcdBase();
  if (base.isEmpty) return '';
  return '$base$bundleId?devkey=${unsealAttributionKey()}&device_id=$deviceId';
}
